package controller.model;
import java.time.LocalDate; import java.time.LocalDateTime; import java.util.*;
import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import controller.model.repository.*; import jakarta.servlet.http.HttpSession;
@Controller public class OperationsController {
 private final DonationRepository donations; private final BloodRequestRepository requests; private final BloodInventoryRepository inventory; private final UserRepository users;
 public OperationsController(DonationRepository d,BloodRequestRepository r,BloodInventoryRepository i,UserRepository u){donations=d;requests=r;inventory=i;users=u;}
 @GetMapping("/records") public String records(HttpSession s,Model m){if(!admin(s))return "redirect:/dashboard";m.addAttribute("donation",new Donation());m.addAttribute("donors",users.findByRoleIgnoreCaseOrderByLastNameAscFirstNameAsc("DONOR"));m.addAttribute("donations",donations.findAllByOrderByDonationDateDesc());add(s,m);return "records";}
 @PostMapping("/records") public String record(Donation d,HttpSession s,RedirectAttributes f){if(!admin(s))return "redirect:/dashboard";if(d.getUserId()==null||d.getDonationDate()==null||d.getUnits()==null||d.getUnits()<1||d.getBloodType()==null||d.getBloodType().isBlank()){f.addFlashAttribute("error","Complete all donation fields.");return "redirect:/records";}d.setStatus("COMPLETED");d.setNextEligibleDate(d.getDonationDate().plusDays(90));donations.save(d);BloodInventory b=inventory.findById(d.getBloodType()).orElseGet(()->{BloodInventory x=new BloodInventory();x.setBloodType(d.getBloodType());x.setUnits(0);return x;});b.setUnits(b.getUnits()+d.getUnits());inventory.save(b);f.addFlashAttribute("success","Donation recorded and blood inventory updated.");return "redirect:/records";}
 @PostMapping("/records/{id}/status") public String donationStatus(@PathVariable Long id,@RequestParam String status,HttpSession s){if(!admin(s))return "redirect:/dashboard";donations.findById(id).ifPresent(d->{d.setStatus(status);donations.save(d);});return "redirect:/records";}
 @GetMapping("/requests") public String requests(HttpSession s,Model m){if(!logged(s))return "redirect:/login";m.addAttribute("request",new BloodRequest());m.addAttribute("requests",requests.findAllByOrderByCreatedAtDesc());add(s,m);return "requests";}
 @PostMapping("/requests") public String createRequest(BloodRequest r,HttpSession s,RedirectAttributes f){if(!admin(s))return "redirect:/dashboard";if(blank(r.getPatientName())||blank(r.getHospital())||blank(r.getBloodType())||r.getUnits()==null||r.getUnits()<1){f.addFlashAttribute("error","Complete the blood request details.");return "redirect:/requests";}r.setStatus("PENDING");r.setCreatedAt(LocalDateTime.now());requests.save(r);f.addFlashAttribute("success","Blood request created.");return "redirect:/requests";}
 @PostMapping("/requests/{id}/status") public String requestStatus(@PathVariable Long id,@RequestParam String status,HttpSession s){if(!admin(s))return "redirect:/dashboard";requests.findById(id).ifPresent(r->{r.setStatus(status);requests.save(r);});return "redirect:/requests";}
 @GetMapping("/reports") public String reports(HttpSession s,Model m){if(!admin(s))return "redirect:/dashboard";m.addAttribute("donors",users.findByRoleIgnoreCaseOrderByLastNameAscFirstNameAsc("DONOR"));m.addAttribute("donations",donations.findAllByOrderByDonationDateDesc());m.addAttribute("requests",requests.findAllByOrderByCreatedAtDesc());m.addAttribute("inventory",inventory.findAll());add(s,m);return "reports";}
 private boolean logged(HttpSession s){return s.getAttribute("userId")!=null;}private boolean admin(HttpSession s){return "ADMIN".equalsIgnoreCase(String.valueOf(s.getAttribute("role")));}private boolean blank(String v){return v==null||v.isBlank();}private void add(HttpSession s,Model m){m.addAttribute("admin",admin(s));m.addAttribute("firstName",s.getAttribute("firstName"));}
}
